function figureHandle = pa_bifurcation_structure()
% PA_BIFURCATION_STRUCTURE Create the manuscript bifurcation figure.
%
%   FIGUREHANDLE = PA_BIFURCATION_STRUCTURE() creates a three-panel figure:
%       A. One-parameter equilibrium branches in z_fixed.
%       B. The healthy-saddle fold in (z_fixed, sigma).
%       C. The cusp-organized fold in (z_fixed, g_z).
%
%   The two-parameter panels use pa_two_parameter_fold_data.mat, generated by
%   pa_two_parameter_folds.m. The function writes
%   pa_bifurcation_structure.png beside this file.

    close all;
    scriptFolder = fileparts(mfilename("fullpath"));
    dataPath = fullfile(scriptFolder, "pa_two_parameter_fold_data.mat");
    outputPath = fullfile(scriptFolder, "pa_bifurcation_structure.png");

    if ~isfile(dataPath)
        error("pa:figure:MissingContinuationData", ...
            "Run pa_two_parameter_folds.m before creating the composite figure.");
    end

    loadedData = load(dataPath, "results");
    results = loadedData.results;
    assertContinuationData(results);

    baseParameters = pa_params();
    branchData = computeEquilibriumBranches(results, baseParameters);

    figureHandle = figure( ...
        Name="PA bifurcation structure", ...
        Color="w", ...
        Position=[50, 40, 1320, 960]);
    layout = tiledlayout(figureHandle, 2, 2, ...
        TileSpacing="compact", Padding="compact");

    regionColors = [ ...
        0.82, 0.94, 0.82; ...
        0.80, 0.86, 0.97; ...
        0.98, 0.83, 0.81];
    colormap(figureHandle, regionColors);

    branchAxes = nexttile(layout, [1, 2]);
    plotEquilibriumBranches(branchAxes, branchData);

    sigmaAxes = nexttile(layout);
    plotTwoParameterPanel( ...
        sigmaAxes, results.sigmaClassification, results.sigmaFold, ...
        results.cuspPoint, "sigma", regionColors);

    gzAxes = nexttile(layout);
    plotTwoParameterPanel( ...
        gzAxes, results.gzClassification, results.gzFold, ...
        results.cuspPoint, "gz", regionColors);

    title(layout, ...
        "Saddle-node threshold and two-parameter organizing structure", ...
        FontSize=17, FontWeight="bold");

    exportgraphics(figureHandle, outputPath, Resolution=300);
    fprintf("Saved composite bifurcation figure to %s\n", outputPath);
end

function assertContinuationData(results)
    requiredFields = [ ...
        "sigmaFold", "gzFold", "cuspPoint", ...
        "sigmaClassification", "gzClassification"];
    for fieldName = requiredFields
        if ~isfield(results, fieldName)
            error("pa:figure:IncompleteContinuationData", ...
                "Continuation data are missing the '%s' field.", fieldName);
        end
    end

    if isempty(results.cuspPoint)
        error("pa:figure:UnverifiedCusp", ...
            "The saved continuation data do not contain a verified cusp.");
    end
end

function branchData = computeEquilibriumBranches(results, baseParameters)
    sigmaFold = results.sigmaFold;
    [~, nominalIndex] = min(abs(sigmaFold.SecondParameter));
    foldZfixed = sigmaFold.zfixed(nominalIndex);
    foldAldosterone = sigmaFold.Aldosterone(nominalIndex);

    belowFold = linspace(0.0, foldZfixed - 1.0e-3, 190);
    allZfixed = linspace(0.0, 0.55, 250);
    healthyAldosterone = nan(size(belowFold));
    saddleAldosterone = nan(size(belowFold));
    diseaseAldosterone = nan(size(allZfixed));

    for index = 1:numel(belowFold)
        parameters = baseParameters;
        parameters.zfixed = belowFold(index);
        roots = findEquilibriumRoots(parameters);
        if numel(roots) ~= 3
            error("pa:figure:UnexpectedEquilibriumCount", ...
                "Expected three equilibria below the nominal fold at z_fixed=%.6f.", ...
                belowFold(index));
        end
        healthyAldosterone(index) = roots(1);
        saddleAldosterone(index) = roots(2);
    end

    for index = 1:numel(allZfixed)
        parameters = baseParameters;
        parameters.zfixed = allZfixed(index);
        roots = findEquilibriumRoots(parameters);
        diseaseAldosterone(index) = roots(end);
    end

    branchData = struct();
    branchData.belowFoldZfixed = [belowFold, foldZfixed];
    branchData.healthyAldosterone = ...
        [healthyAldosterone, foldAldosterone];
    branchData.saddleAldosterone = ...
        [saddleAldosterone, foldAldosterone];
    branchData.allZfixed = allZfixed;
    branchData.diseaseAldosterone = diseaseAldosterone;
    branchData.foldZfixed = foldZfixed;
    branchData.foldAldosterone = foldAldosterone;
end

function roots = findEquilibriumRoots(parameters)
    aldosteroneGrid = linspace(0.0, 10.0, 8001);
    residual = scalarEquilibriumResidual(aldosteroneGrid, parameters);
    crossingIndices = find(residual(1:end - 1).*residual(2:end) < 0.0);
    roots = nan(1, numel(crossingIndices));

    for index = 1:numel(crossingIndices)
        bracket = aldosteroneGrid( ...
            crossingIndices(index):crossingIndices(index) + 1);
        roots(index) = fzero( ...
            @(aldosterone) scalarEquilibriumResidual( ...
            aldosterone, parameters), bracket);
    end
    roots = unique(round(roots, 11));
end

function residual = scalarEquilibriumResidual(aldosterone, parameters)
    saltState = min(max( ...
        hillValue(aldosterone, parameters.Ks, parameters.ns) + ...
        parameters.sodium, 0.0), 0.999);
    renin = parameters.r0*(1.0 - saltState)/parameters.kr;
    plasticCapacity = (parameters.gz/parameters.kz)* ...
        hillValue(saltState, parameters.Kz, parameters.nz);
    activeFraction = parameters.fmin + (1.0 - parameters.fmin)* ...
        hillValue(saltState, parameters.Kf, parameters.nf);
    reninProduction = parameters.beta* ...
        hillValue(renin, parameters.Kr, parameters.pr);

    residual = reninProduction + ...
        parameters.alpha*(parameters.zfixed + ...
        plasticCapacity.*activeFraction) - ...
        parameters.ka*aldosterone;
end

function value = hillValue(input, halfSaturation, exponent)
    inputPower = input.^exponent;
    value = inputPower./(halfSaturation^exponent + inputPower);
end

function plotEquilibriumBranches(axesHandle, branchData)
    hold(axesHandle, "on");
    box(axesHandle, "on");
    grid(axesHandle, "on");

    bistableShade = patch(axesHandle, ...
        [0.0, branchData.foldZfixed, branchData.foldZfixed, 0.0], ...
        [0.0, 0.0, 5.4, 5.4], ...
        [0.80, 0.86, 0.97], ...
        FaceAlpha=0.22, EdgeColor="none", ...
        HandleVisibility="off");
    diseaseShade = patch(axesHandle, ...
        [branchData.foldZfixed, 0.55, 0.55, branchData.foldZfixed], ...
        [0.0, 0.0, 5.4, 5.4], ...
        [0.98, 0.83, 0.81], ...
        FaceAlpha=0.20, EdgeColor="none", ...
        HandleVisibility="off");

    diseaseLine = plot(axesHandle, ...
        branchData.allZfixed, branchData.diseaseAldosterone, ...
        Color=[0.10, 0.32, 0.78], LineWidth=2.4, ...
        DisplayName="disease node (stable)");
    healthyLine = plot(axesHandle, ...
        branchData.belowFoldZfixed, branchData.healthyAldosterone, ...
        Color=[0.05, 0.62, 0.25], LineWidth=2.4, ...
        DisplayName="healthy node (stable)");
    saddleLine = plot(axesHandle, ...
        branchData.belowFoldZfixed, branchData.saddleAldosterone, ...
        "--", Color=[0.84, 0.15, 0.15], LineWidth=2.0, ...
        DisplayName="saddle (unstable)");
    foldMarker = plot(axesHandle, ...
        branchData.foldZfixed, branchData.foldAldosterone, ...
        "ko", MarkerFaceColor=[1.0, 0.72, 0.08], MarkerSize=8, ...
        DisplayName="saddle-node fold");
    xline(axesHandle, branchData.foldZfixed, "k:", ...
        LineWidth=1.3, HandleVisibility="off");

    text(axesHandle, branchData.foldZfixed + 0.012, 1.35, ...
        sprintf("z_{fixed}^{*}=%.3f", branchData.foldZfixed), ...
        FontSize=10, BackgroundColor="w", Margin=2);
    text(axesHandle, 0.11, 5.05, "bistable", ...
        Color=[0.15, 0.28, 0.58], FontWeight="bold");
    text(axesHandle, 0.43, 5.05, "disease-only", ...
        Color=[0.58, 0.20, 0.16], FontWeight="bold");

    xlabel(axesHandle, "suppression-resistant capacity z_{fixed}");
    ylabel(axesHandle, "equilibrium aldosterone a");
    title(axesHandle, ...
        "(A) One-parameter equilibrium branches", ...
        FontWeight="bold");
    xlim(axesHandle, [0.0, 0.55]);
    ylim(axesHandle, [0.0, 5.4]);
    legend(axesHandle, ...
        [diseaseLine, healthyLine, saddleLine, foldMarker], ...
        Location="southoutside", Orientation="horizontal", ...
        NumColumns=4, FontSize=9);

    uistack(bistableShade, "bottom");
    uistack(diseaseShade, "bottom");
end

function plotTwoParameterPanel( ...
        axesHandle, classification, foldTable, cuspPoint, ...
        planeName, regionColors)
    imagesc(axesHandle, ...
        classification.parameterValues, ...
        classification.zfixedValues, ...
        double(classification.regionClass));
    set(axesHandle, YDir="normal");
    clim(axesHandle, [0.5, 3.5]);
    hold(axesHandle, "on");
    box(axesHandle, "on");
    grid(axesHandle, "on");

    physical = ...
        (foldTable.SecondParameter >= min(classification.parameterValues)) & ...
        (foldTable.SecondParameter <= max(classification.parameterValues)) & ...
        (foldTable.zfixed >= min(classification.zfixedValues)) & ...
        (foldTable.zfixed <= max(classification.zfixedValues));
    foldLine = plot(axesHandle, ...
        foldTable.SecondParameter(physical), ...
        foldTable.zfixed(physical), ...
        "k-", LineWidth=2.5, DisplayName="fold locus");

    healthyPatch = patch(axesHandle, NaN, NaN, regionColors(1, :), ...
        EdgeColor="none", DisplayName="healthy-only");
    bistablePatch = patch(axesHandle, NaN, NaN, regionColors(2, :), ...
        EdgeColor="none", DisplayName="bistable");
    diseasePatch = patch(axesHandle, NaN, NaN, regionColors(3, :), ...
        EdgeColor="none", DisplayName="disease-only");

    switch planeName
        case "sigma"
            xlabel(axesHandle, "dietary sodium bias \sigma");
            ylabel(axesHandle, "suppression-resistant capacity z_{fixed}");
            title(axesHandle, ...
                "(B) Fold curve in (z_{fixed}, \sigma)", ...
                FontWeight="bold");
            legend(axesHandle, ...
                [bistablePatch, diseasePatch, foldLine], ...
                Location="northeast", FontSize=8);
        case "gz"
            cuspMarker = plot(axesHandle, cuspPoint(6), cuspPoint(5), ...
                "ko", MarkerFaceColor=[1.0, 0.72, 0.08], MarkerSize=8, ...
                DisplayName="cusp");
            xlabel(axesHandle, "salt-bridge strength g_z");
            ylabel(axesHandle, "suppression-resistant capacity z_{fixed}");
            title(axesHandle, ...
                "(C) Cusp in (z_{fixed}, g_z)", ...
                FontWeight="bold");
            legend(axesHandle, ...
                [healthyPatch, bistablePatch, diseasePatch, ...
                foldLine, cuspMarker], ...
                Location="northeast", FontSize=8);
        otherwise
            error("pa:figure:UnknownPlane", ...
                "Unknown two-parameter panel '%s'.", planeName);
    end
end
